{
 "research_question": "Does changing the offensive five (lineup personnel) significantly alter a team's shot mix?",
 "retrieval_summary": {
  "prior_findings": [
   {
    "id": "FAM:SM1",
    "status": "supported",
    "summary": "Shot mix is a stable team characteristic and is influenced by the offensive system (coach's strategy) and the players on the court."
   },
   {
    "id": "FAM:SM2",
    "status": "supported",
    "summary": "Shot mix is not strongly influenced by the defensive personnel, suggesting offensive personnel and system are primary drivers."
   }
  ],
  "failed_experiments": [],
  "limitations": [
   {
    "id": "FAM:SM1",
    "text": "The study noted that offensive systems are often tied to specific personnel; disentangling the effect of personnel from system is challenging. It also mentioned that shot mix varies over the season due to fatigue, injuries, and strategic adjustments."
   }
  ],
  "unresolved": [
   {
    "id": "FAM:SM1",
    "text": "The study did not quantify the specific impact of changing personnel on shot mix, focusing more on the overall stability and influence of system/personnel broadly."
   }
  ]
 },
 "evidence_use": "The retrieved information from FAM:SM1 and FAM:SM2 indicates that shot mix is indeed influenced by personnel, which supports the premise of the research question. Specifically, FAM:SM1 states that 'shot mix is influenced by [...] the players on the court,' and FAM:SM2 notes that offensive personnel are primary drivers. This suggests that the effect is likely real and detectable. However, FAM:SM1 also highlights the challenge of disentangling personnel effects from system effects and the variability of shot mix over a season, which are important methodological considerations. The prior work did not specifically quantify the magnitude of shot mix change due to personnel changes, leaving this question open for investigation.",
 "testability": {
  "p_testable": 0.8,
  "blocking_constraints": []
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SM1",
   "FAM:SM2"
  ],
  "summary": "Prior work (FAM:SM1, FAM:SM2) has established that shot mix is influenced by the offensive personnel on the court and is a relatively stable team characteristic. However, it did not specifically quantify the change in shot mix attributable to specific personnel changes within a lineup, nor did it fully disentangle personnel effects from system effects. The question of whether a specific change in the offensive five *itself* moves shot mix, and by how much, remains open."
 },
 "risks": [
  {
   "code": "CONFOUNDING",
   "text": "Offensive system and coaching strategy are highly confounded with personnel choices, making it challenging to isolate the effect of personnel changes alone. A coach might change personnel to implement a different strategy, or a strategy might only be viable with specific personnel."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "Lineup changes occur frequently, but specific offensive five combinations might not have enough minutes together to yield stable shot mix statistics, especially when attempting to isolate the effect of one or two player changes within a lineup."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "Shot mix can evolve over a season due to player development, injuries, fatigue, and strategic adjustments (as noted in FAM:SM1). This non-stationarity can confound the observed effects of lineup changes if not properly accounted for (e.g., by using within-season comparisons or time-based controls)."
  }
 ],
 "predicted_outcome": {
  "supported": 0.6,
  "rejected": 0.1,
  "untestable": 0.15,
  "artifact": 0.1,
  "uncertain": 0.05
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of changing one or more players in a team's offensive five lineup on the team's subsequent shot mix, specifically focusing on the proportion of attempts from different shot zones (e.g., restricted area, mid-range, three-point line).",
  "unit": "Offensive possession for a specific team.",
  "sample": "All offensive possessions from the 2022-23, 2023-24, and 2024-25 NBA regular seasons and playoffs. The analysis will focus on transitions between different five-player offensive lineups for the same team, considering only changes involving 1-2 players to better isolate personnel effects. Lineups with fewer than a minimum threshold of possessions (e.g., 50-100 possessions) will be excluded to ensure statistical stability.",
  "power": "Achieve 80% power to detect a 2-percentage-point change in the proportion of shots from a specific zone (e.g., 3-point attempts) with a significance level of alpha = 0.05, assuming an average baseline proportion of 35% and a standard deviation derived from historical data. This will require a sufficient number of lineup transitions and subsequent possessions for analysis.",
  "controls": "Match on recent offensive efficiency (e.g., points per 100 possessions over the prior 50 possessions), opponent defensive rating, game state (score differential, quarter, time remaining), and home/away status. Use fixed effects for team and opponent to control for baseline differences. Consider using player-level fixed effects for players entering/exiting the lineup if feasible to control for individual player tendencies. A difference-in-differences approach could compare shot mix before and after a lineup change, controlling for contemporaneous team-level trends.",
  "falsification": "If changes in defensive personnel on the opposing team are found to correlate strongly with changes in the observed team's shot mix, it would cast doubt on the claim that offensive personnel changes are the primary driver, as prior work (FAM:SM2) suggests this is not the case. Additionally, if 'placebo' lineup changes (e.g., changes that occur due to timeouts rather than substitutions) show similar shot mix shifts, it would suggest an artifact.",
  "multiplicity": "Adjust p-values for multiple comparisons if testing changes across multiple shot zones (e.g., restricted area, mid-range, three-point) or for multiple types of lineup changes (e.g., 1-player vs. 2-player changes). A Bonferroni correction or False Discovery Rate control will be applied.",
  "decision_rule": "The research question will be considered 'supported' if there is a statistically significant (p < 0.05 after multiplicity adjustment) and substantively meaningful (e.g., >= 2 percentage point change) alteration in at least one key shot mix category (e.g., 3-point attempt rate, restricted area attempt rate) following a change in offensive personnel, after controlling for confounding factors. The 'design can detect personnel effects' aspect will be inferred if such an effect is observed.",
  "data_version": "NBA 2022-23 regular season and playoffs, NBA 2023-24 regular season and playoffs, NBA 2024-25 regular season and playoffs. Data will be derived from play-by-play, substitution rotation intervals, and derived play-type possession records."
 }

